function main(): void {
  const inputs: string[] = ["2030-01-01 10:20", "2030-01-01 10:20:30", "Tue, 01 Jan 2030 00:00:00 GMT", "Jan 1, 2030", "January 1, 2030 10:00:00", "1 Jan 2030", "2030/01/02", "Jan 1, 2030 3:04 PM", "Tue Jan 01 2030 00:00:00 GMT+0100", "2030-01-01T00:00:00.5Z", "garbage", "Foo 1, 2030"];
  for (const s of inputs) { console.log(s, Date.parse(s)); }
  console.log(new Date("Tue, 01 Jan 2030 00:00:00 GMT").toISOString());
}
